contract InvMutTest is Test {
    C c;
    address pauser = address(0xA11CE);

    function setUp() public {
        c = new C();
        PriceFeed pf = new PriceFeed();
        TokenMock col = new TokenMock("Coll", "COL", 18);
        TokenMock bor = new TokenMock("Borr", "BOR", 18);

        InitializeFeeConfigParams memory f = InitializeFeeConfigParams({
