// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    MockERC20 collateralToken;

    function setUp() public {
        c = new C();

        collateralToken = new MockERC20();
        MockERC20 borrowToken = new MockERC20();
        MockERC20 weth = new MockERC20();
        MockPriceFeed priceFeed = new MockPriceFeed();

        InitializeFeeConfigParams memory f = InitializeFeeConfigParams({
            swapFeeAPR: 0.05e18,
            fragmentationFee: 1,
            liquidationRewardPercent: 0.01e18,
            overdueCollateralProtocolPercent: 0,
            collateralProtocolPercent: 0,
            feeRecipient: makeAddr("feeRecipient")
        });
        InitializeRiskConfigParams memory r = InitializeRiskConfigParams({
            crOpening: 1.5e18,
            crLiquidation: 1.2e18,
            minimumCreditBorrowAToken: 1,
            borrowATokenCap: type(uint256).max,
            minTenor: 1,
            maxTenor: 365 days
        });
        InitializeOracleParams memory o = InitializeOracleParams({
            priceFeed: address(priceFeed),
            variablePoolBorrowRateStaleRateInterval: 1 days
        });
        InitializeDataParams memory d = InitializeDataParams({
            weth: address(weth),
            underlyingCollateralToken: address(collateralToken),
            underlyingBorrowToken: address(borrowToken),
            variablePool: makeAddr("variablePool")
        });

        c.initialize(address(this), f, r, o, d);
    }

    function testFuzz_property(uint256 amount, address to) public {
        vm.assume(to != address(0));
        amount = bound(amount, 1, type(uint256).max);

        // pause the protocol via the public admin entry point
        c.pause();

        // drive c through the public deposit entry point while paused
        (bool ok, ) = address(c).call(
            abi.encodeWithSignature(
                "deposit((address,uint256,address))",
                address(collateralToken),
                amount,
                to
            )
        );

        // GENERAL RULE: for any admissible deposit, a paused protocol must reject it.
        assertTrue(!ok, "deposit must revert while the protocol is paused");
    }
}

