// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0xA11CE);

    function setUp() public {
        c = new C();
        // initialize with a valid configuration so roles (PAUSER_ROLE) are granted
        C.InitializeFeeConfigParams memory f = C.InitializeFeeConfigParams({
            swapFeeAPR: 0,
            fragmentationFee: 0,
            liquidationRewardPercent: 0,
            overdueCollateralProtocolPercent: 0,
            collateralProtocolPercent: 0,
            feeRecipient: address(0xFEE)
        });
        C.InitializeRiskConfigParams memory r = C.InitializeRiskConfigParams({
            crOpening: 2e18,
            crLiquidation: 1.5e18,
            minimumCreditBorrowAToken: 1,
            borrowATokenCap: 0,
            minTenor: 1,
            maxTenor: 365 days
        });
        MockFeed feed = new MockFeed();
        C.InitializeOracleParams memory o = C.InitializeOracleParams({
            priceFeed: address(feed),
            variablePoolBorrowRateStaleRateInterval: 0
        });
        MockToken collateral = new MockToken(18);
        MockToken borrow = new MockToken(18);
        C.InitializeDataParams memory d = C.InitializeDataParams({
            weth: address(0xW3),
            underlyingCollateralToken: address(collateral),
            underlyingBorrowToken: address(borrow),
            variablePool: address(0xP00L)
        });
        c.initialize(owner, f, r, o, d);
    }

    function testFuzz_property(uint256 openingLimitBorrowCR, bool allDisabled, bool forSale) public {
        // the admin pauses the protocol
        vm.prank(owner);
        c.pause();

        uint256[] memory ids = new uint256[](0);
        C.SetUserConfigurationParams memory params = C.SetUserConfigurationParams({
            openingLimitBorrowCR: openingLimitBorrowCR,
            allCreditPositionsForSaleDisabled: allDisabled,
            creditPositionIdsForSale: forSale,
            creditPositionIds: ids
        });

        // GENERAL RULE: while paused, every setUserConfiguration call (any params) must revert
        bool ok;
        vm.prank(owner);
        try c.setUserConfiguration(params) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok, "setUserConfiguration must revert while the protocol is paused");
    }
}

contract MockFeed {
    function getPrice() external pure returns (uint256) {
        return 1e18;
    }
}

contract MockToken {
    string public name = "Mock";
    string public symbol = "MK";
    uint8 public decimals;

    constructor(uint8 d) {
        decimals = d;
    }
}
